def transform_fixed(grid):
    S = len(grid)
    result = [[0] * S for _ in range(S)]

    # For 8x8, center should be a 2x2 at rows 3-4 and cols 3-4
    center_start = S // 2 - 1  # 8//2 - 1 = 3

    # 2x2 center
    for r in range(center_start, center_start + 2):
        for c in range(center_start, center_start + 2):
            result[r][c] = 2

    # UL ray: before center starts
    for r in range(center_start):
        result[r][r] = 8

    # UR ray: r + c = S - 2, before center
    for r in range(center_start):
        c = S - 2 - r
        if 0 <= c < S:
            result[r][c] = 3

    # DR ray: after center ends
    for r in range(center_start + 2, S):
        c = r
        if 0 <= c < S:
            result[r][c] = 6

    # DL ray: after center ends
    for r in range(center_start + 2, S):
        c = S - 2 - r
        if 0 <= c < S:
            result[r][c] = 7

    return result

